{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "This bill would require the Tennessee comptroller’s office to review foundational literacy skills plans submitted to the Department of Education for approval. The review would examine whether plans meet the requirements of subsection (f) and state board rules",
      "rationale": "Identifies the responsible office, the plans subject to review, and both compliance standards."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The review would examine whether plans meet the requirements of subsection (f) and state board rules, whether the department initially approved or denied them, and what revisions or amendments the department required for approval.",
      "rationale": "Covers examination of initial approval or denial and required revisions or amendments. Omitting the option to use a designee does not materially change the comptroller’s review responsibility."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The comptroller would include the review’s findings in a report.",
      "rationale": "Conveys the requirement to report the literacy-plan findings; the surrounding summary identifies the required triennial report, making the statutory cross-reference unnecessary."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Every three years, the comptroller would submit a report on its review of data, practices, and outcomes related to this part",
      "rationale": "Conveys the comptroller’s required review and all three categories within its statutory scope."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The department would have to provide information the comptroller requests as soon as practicable.",
      "rationale": "Identifies the department’s duty to supply requested information and preserves the timing requirement."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "Every three years, the comptroller would submit a report on its review of data, practices, and outcomes related to this part to the Senate Education Committee chair, the House committee chair responsible for student literacy, and the State Board of Education, and publish it on the comptroller’s website.",
      "rationale": "Includes the reporting interval, report subject, all required recipients, and website publication."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The bill would take effect when it becomes law.",
      "rationale": "Accurately conveys the effective-date provision."
    }
  ]
}
